from mk import *

def fig():
    g = Fig(560, 260, "תרשים א: האנרגיה הקינטית של התיבה כפונקציה של המקום: 16 ג'אול קבועה עד 20 מטר, ואחר כך עולה בקו ישר ל-40 ג'אול ב-50 מטר. תרשים ב: אנרגיית הגובה כפונקציה של האנרגיה הקינטית: קו ישר מ-10 ג'אול ל-0")
    X, Y = g.graph(60, 220, 210, 170, "x (m)", "Ek (J)", xticks=[(20, "20"), (50, "50")], yticks=[(16, "16"), (40, "40")], xmax=60, ymax=45, grid=False)
    g.plot(X, Y, [(0, 16), (20, 16), (50, 40)]); g.guide(X, Y, 50, 40); g.line(X(20), Y(16), X(20), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    g.heb(160, 252, "תרשים א")
    X, Y = g.graph(340, 220, 180, 170, "Ek (J)", "Ep (J)", xticks=[(v, str(v)) for v in (2, 4, 6, 8, 10, 12)], yticks=[(v, str(v)) for v in (2, 4, 6, 8, 10, 12)], xmax=12, ymax=12)
    g.plot(X, Y, [(0, 10), (10, 0)])
    for i in range(11): g.dot(X(i), Y(10 - i), 2.5)
    g.heb(430, 252, "תרשים ב")
    return g

E(id="bagrut-2009-q4", year=2009, label="2009 שאלה 4", topic="energy", sub="en-friction", diff=3, fig=fig,
  stem=r"תיבה שמסתה $0.5$ ק\"ג נעה לאורך קו ישר על משטח אופקי מחוספס בכיוון החיובי של ציר ה-$x$. מקדם החיכוך הקינטי בין התיבה למשטח הוא $\mu_k = 0.1$. בזמן $t = 0$ הייתה התיבה בנקודה ששיעורה $x = 0$. הגרף בתרשים א מתאר את האנרגיה הקינטית, $E_k$, של התיבה כפונקציה של מיקומה, $x$, ב-$50$ המטרים הראשונים של תנועתה.",
  parts=[
    P("א", r"האם במהלך $20$ המטרים הראשונים של התנועה פועל על התיבה כוח אופקי בנוסף לכוח החיכוך? הסבר את תשובתך.", choice(["כן", "לא"], 0), ["graph", "principle"], [
        S(r"האנרגיה הקינטית קבועה", r"לפי משפט העבודה והאנרגיה, העבודה הכוללת אפס. החיכוך עושה עבודה שלילית, ולכן חייב להיות כוח שמאזן אותו", r"W = \Delta E_k = 0"),
    ], r"כן: האנרגיה הקינטית לא יורדת למרות החיכוך", key=r"כן"),
    P("ב", r"במהלך תנועת התיבה מ-$x = 20\,\text{m}$ ל-$x = 50\,\text{m}$, פועל על התיבה כוח אופקי קבוע $F_1$, בנוסף לכוח החיכוך. חשב את גודל הכוח $F_1$.", num(1.3, "N"), ["graph", "principle"], [
        S(r"כוח החיכוך", r"μmg", r"f = 0.1 \cdot 0.5 \cdot 10 = 0.5\,\text{N}"),
        S(r"משפט העבודה והאנרגיה", r"עבודת השקול על 30 m", r"(F_1 - 0.5) \cdot 30 = 40 - 16"),
        S(r"פותרים", r"מחלקים ב-30", r"F_1 = 0.8 + 0.5 = 1.3\,\text{N}"),
    ], r"$1.3\,\text{N}$", key=r"F1=1.3 N"),
    P("ג", r"הכוח $F_1$ הפסיק לפעול ברגע שהתיבה הגיעה ל-$x = 50\,\text{m}$. חשב את העבודה של כוח החיכוך בקטע התנועה מ-$x = 0$ עד שהתיבה נעצרה.", num(-65, "J"), ["principle", "signs"], [
        S(r"הדרך אחרי $50\,\text{m}$", r"החיכוך מוריד $40\,\text{J}$", r"0.5\,d = 40 \Rightarrow d = 80\,\text{m}"),
        S(r"העבודה", r"דרך כוללת $130\,\text{m}$", r"W_f = -0.5 \cdot 130 = -65\,\text{J}"),
    ], r"$-65\,\text{J}$", key=r"Wf=−65 J"),
    P("ד", r"נניח שבקטע מ-$x = 20\,\text{m}$ ל-$x = 50\,\text{m}$ היו מפעילים על התיבה, במקום הכוח $F_1$, כוח $F_2$ שנטוי בזווית $\alpha$ מעל האופק, כך שהרכיב האופקי שלו היה שווה ל-$F_1$. האם במקרה זה האנרגיה הקינטית של התיבה ב-$x = 50\,\text{m}$ הייתה שווה ל-$40\,\text{J}$, גדולה מ-$40\,\text{J}$ או קטנה מ-$40\,\text{J}$? הסבר.", choice(["שווה", "גדולה", "קטנה"], 1), ["fbd", "principle"], [
        S(r"הרכיב האנכי", r"מרים מעט את התיבה ומקטין את הנורמלי, ולכן גם את החיכוך", r"N = mg - F_2\sin\alpha < mg"),
        S(r"מסקנה", r"אותה עבודה של הכוח, פחות עבודה של חיכוך", r"E_k > 40\,\text{J}"),
    ], r"גדולה: החיכוך קטן", key=r"גדולה מ-40 J"),
    P("ה", r"גוף קטן נע על פני משטח כלשהו. הגרף בתרשים ב מתאר את הקשר בין האנרגיה הפוטנציאלית הכובדית של הגוף לבין האנרגיה הקינטית שלו. לפניך שלושה היגדים: (1) הגוף נע על משטח אופקי חלק בהשפעת כוח קבוע. (2) הגוף נע במורד מישור משופע מחוספס. (3) הגוף נופל חופשית. איזה היגד מתאים לגרף?", choice(["(1)", "(2)", "(3)"], 2), ["graph", "principle"], [
        S(r"מה הגרף אומר", r"סכום שתי האנרגיות קבוע", r"E_p + E_k = 10\,\text{J}"),
        S(r"פוסלים", r"ב-(1) אנרגיית הגובה קבועה. ב-(2) האנרגיה המכנית יורדת בגלל החיכוך", r"\Delta E \ne 0"),
    ], r"(3): רק בנפילה חופשית האנרגיה המכנית נשמרת ואנרגיית הגובה הופכת לקינטית", key=r"היגד 3 מתאים"),
  ],
  concepts=["משפט העבודה והאנרגיה", "עבודת חיכוך", "כוח נטוי ונורמלי", "שימור אנרגיה מכנית"],
  summary=r"תיבה על משטח מחוספס לפי גרף אנרגיה קינטית: מתי פועל כוח נוסף, כמה, עבודת החיכוך הכוללת, ומה מתאים לגרף של אנרגיה נשמרת.")
